!function(e){function r(r){for(var a,i,p=r[0],o=r[1],d=r[2],y=0,c=[];y<p.length;y++)i=p[y],Object.prototype.hasOwnProperty.call(n,i)&&n[i]&&c.push(n[i][0]),n[i]=0;for(a in o)Object.prototype.hasOwnProperty.call(o,a)&&(e[a]=o[a]);for(s&&s(r);c.length;)c.shift()();return m.push.apply(m,d||[]),t()}function t(){for(var e,r=0;r<m.length;r++){for(var t,i=m[r],p=!0,o=1;o<i.length;o++)t=i[o],0!==n[t]&&(p=!1);p&&(m.splice(r--,1),e=a(a.s=i[0]))}return e}function a(r){if(i[r])return i[r].exports;var t=i[r]={i:r,l:!1,exports:{}};return e[r].call(t.exports,t,t.exports,a),t.l=!0,t.exports}var i={},n={34:0},m=[];a.m=e,a.c=i,a.d=function(e,r,t){a.o(e,r)||Object.defineProperty(e,r,{enumerable:!0,get:t})},a.r=function(e){"undefined"!=typeof Symbol&&Symbol.toStringTag&&Object.defineProperty(e,Symbol.toStringTag,{value:"Module"}),Object.defineProperty(e,"__esModule",{value:!0})},a.t=function(e,r){if(1&r&&(e=a(e)),8&r)return e;if(4&r&&"object"==typeof e&&e&&e.__esModule)return e;var t=Object.create(null);if(a.r(t),Object.defineProperty(t,"default",{enumerable:!0,value:e}),2&r&&"string"!=typeof e)for(var i in e)a.d(t,i,function(r){return e[r]}.bind(null,i));return t},a.n=function(e){var r=e&&e.__esModule?function(){return e.default}:function(){return e};return a.d(r,"a",r),r},a.o=function(e,r){return Object.prototype.hasOwnProperty.call(e,r)},a.p="";var p=window.webpackJsonp=window.webpackJsonp||[],o=p.push.bind(p);p.push=r,p=p.slice();for(var d=0;d<p.length;d++)r(p[d]);var s=o;m.push([42,0]),t()}({42:function(e,r,t){"use strict";t.r(r);var a=t(0);Object(a.a)("de","army",t(43),t(1))},43:function(e){e.exports=JSON.parse('{"category":[{"name":"德国","link":"de_shortcut"},{"name":"陆战武器","link":"de_army"},{"name":"坦克歼击车","link":"de_army#de_army_tankdestroyer"}],"model":"Ⅳ号坦克歼击车","description":"<p>随着欧洲战场的战事不断激烈，德军现有的反坦克装备已难以抵挡数量庞大的苏军与盟军坦克的攻击，为此，德军在加紧生产Ⅳ号坦克的同时，也在Ⅳ号坦克的底盘上加装反坦克火炮，改装为坦克歼击车来装备德军反坦克部队。Ⅳ号坦克歼击车的火炮有两种型号，一种是安装48倍口径75mm火炮的L/48型，另一种是安装70倍口径75mm火炮的L/70型。</p><p>Ⅳ号坦克歼击车整车低矮，前装甲倾角很大，装甲厚度60mm（后期达到80mm），有较强的防护能力；L/70型的75mm火炮威力很大，发射装甲弹可在1500m距离上击穿苏制T34坦克的正面装甲，而对付防护力稍弱的英美制中型坦克，就更具有优势。然而，由于Ⅳ号坦克歼击车出现时已是二战后期，德军在战场上是大势已去，在数量众多的苏军与盟军坦克面前，Ⅳ号坦克歼击车最终也大多落入被击毁或被遗弃的地步。</p>","part1title":"","part1description":"","part1content":[{"image":"imgs/de/army/de_army_tankdestroyeriv_11.jpg","description":"<span>L/48 Ⅳ号坦克歼击车三视图</span><br><span>型号：Panzer Ⅳ Sd Kfz 162</span>","caption":""},{"image":"imgs/de/army/de_army_tankdestroyeriv_12.jpg","description":"<span>L/70 Ⅳ号坦克歼击车三视图</span><br><span>型号：Panzer Ⅳ Sd Kfz 162/1</span>","caption":""},{"image":"{{text}}安装有炮口制退步器的Pak39型48倍口径75mm火炮（L/48）Ⅳ号坦克歼击车{{image}}imgs/de/army/de_army_tankdestroyeriv_13.jpg{{text}}没有炮口制退步器的Pak39型48倍口径75mm火炮（L/48）Ⅳ号坦克歼击车{{image}}imgs/de/army/de_army_tankdestroyeriv_14.jpg","description":"<h6>L/48 Ⅳ号坦克歼击车</h6><p>参数：</p><p>车长：6.85m，车宽：3.17m，车高：1.85m，车重：24.25t；乘员：4人。</p><p>装甲厚度：正面80mm，侧面：40mm；</p><p>最高车速：40km，最大行程：210km；</p><p>武器配备：1门Pak39型48倍口径75mm火炮，1挺7.92mmMG34机枪（前期配2挺）。</p><p>L/48型坦克歼击车在1944年1月开始生产，至同年11月一共生产了769辆</p>","caption":""},{"image":"{{text}}安装Kwk42型70倍口径75mm火炮（L/70A）Ⅳ号坦克歼击车{{image}}imgs/de/army/de_army_tankdestroyeriv_15.jpg{{text}}安装Kwk42型70倍口径75mm火炮（L/70V）Ⅳ号坦克歼击车{{image}}imgs/de/army/de_army_tankdestroyeriv_16.jpg","description":"<h6>L/70 Ⅳ号坦克歼击车</h6><p>参数：</p><p>车长：8.5m，车宽：3.17m，车高：1.85m，车重：24.8t；乘员：4人。</p><p>装甲厚度：正面80mm，侧面：40mm；</p><p>最高车速：35km，最大行程：210km；</p><p>武器配备：1门Kwk42型70倍口径75mm火炮，1挺7.92mm机枪（MG34）</p><p>L/70坦克歼击车是L/48的改进型，该车在1944年8月投产，一共生产了930辆。该型车首先装备德军第105和106独立装甲旅，后又装备了各独立反坦克营。首次大规模参战是在1944年12月在西线与盟军作战的阿登反击战。</p>","caption":""}],"part2title":"战场上的Ⅳ号坦克歼击车","part2description":"","part2content":[{"image":"imgs/de/army/de_army_tankdestroyeriv_21.jpg","description":"1944年12月，德军第116装甲师第225反坦克营的一辆安装有炮口制退器的Pak39型48倍口径75mm火炮（L/48）Ⅳ号坦克歼击车（Panzer Ⅳ Sd Kfz 162）。","caption":""},{"image":"imgs/de/army/de_army_tankdestroyeriv_22.jpg","description":"1944年7月东线战场，德军一辆不明单位的（L/48）Ⅳ号坦克歼击车（Panzer Ⅳ Sd Kfz 162），该车车体周边已装上了装甲裙板以加强防护。","caption":""},{"image":"imgs/de/army/de_army_tankdestroyeriv_23.jpg","description":"1945年3月德国战场，德军第2装甲师第38反坦克营的一辆已拆除炮口制退器的Pak39型48倍口径75mm火炮（L/48）Ⅳ号坦克歼击车（Panzer Ⅳ Sd Kfz 162）。","caption":""},{"image":"imgs/de/army/de_army_tankdestroyeriv_24.jpg","description":"1945年3月东线匈牙利战场，德军一辆不明单位的安装Kwk42型70倍口径75mm火炮（L/70A）Ⅳ号坦克歼击车（Panzer Ⅳ Sd Kfz 162/1）。","caption":""},{"image":"imgs/de/army/de_army_tankdestroyeriv_25.jpg","description":"1945年3月东线匈牙利战场，一辆隶属德国武装党卫军第12装甲师（或武装党卫军第9装甲师）的（L/70V）Ⅳ号坦克歼击车（Panzer Ⅳ Sd Kfz 162/1）；该车车体周边已装上了装甲防护裙板。","caption":""},{"image":"imgs/de/army/de_army_tankdestroyeriv_26.jpg","description":"1945年春天，东线捷克斯洛伐克中部摩拉维亚地区，一辆隶属德军第17装甲师的（L/70V）Ⅳ号坦克歼击车（Panzer Ⅳ Sd Kfz 162/1）。","caption":""},{"image":"imgs/de/army/de_army_tankdestroyeriv_27.jpg","description":"1944年7月法国战场，德军第116装甲师第228反坦克营的（L/48）Ⅳ号坦克歼击车正在向诺曼第地区进发，以阻击登陆的盟军部队。","caption":""},{"image":"imgs/de/army/de_army_tankdestroyeriv_28.jpg","description":"1944年在法国诺曼第战场，一些美军官兵围坐在一辆被击毁的德军（L/48）Ⅳ号坦克歼击车上，显然，此时德军的反登陆作战已告失败。","caption":""},{"image":"imgs/de/army/de_army_tankdestroyeriv_29.jpg","description":"1944年夏天东线战场，德军反坦克营（单位不明）的一辆（L/48）Ⅳ号坦克歼击车正在向前线进发。","caption":""},{"image":"imgs/de/army/de_army_tankdestroyeriv_30.jpg","description":"1944年夏天东线战场，德军（单位不明）一辆（L/48）Ⅳ号坦克歼击车正搭载士兵在回撒途中。","caption":""},{"image":"imgs/de/army/de_army_tankdestroyeriv_31.jpg","description":"1945年3月东线匈牙利Lake Balaton地区，一辆被德军（单位不明）遗弃的（L/48）Ⅳ号坦克歼击车。","caption":""},{"image":"imgs/de/army/de_army_tankdestroyeriv_32.jpg","description":"1945年西线战场，德军一反坦克营（单位不明）的（L/70V）Ⅳ号坦克歼击车伴随步兵一起向前线进发。","caption":""},{"image":"imgs/de/army/de_army_tankdestroyeriv_33.jpg","description":"1945年春天德国东普鲁士地区，德军一辆（L/48）Ⅳ号坦克歼击车（单位不明）被遗弃在城镇一道路旁，该城镇经历了一场激烈的战斗。","caption":""},{"image":"imgs/de/army/de_army_tankdestroyeriv_34.jpg","description":"1945年春西线，德军（单位不明）一辆正在撒退的（L/70V）Ⅳ号坦克歼击车被盟军飞机空袭击毁在桥上。","caption":""},{"image":"imgs/de/army/de_army_tankdestroyeriv_35.jpg","description":"1945年3月西线战场，英军官兵在检查一辆被德军（单位不明）遗弃的（L/70V）Ⅳ号坦克歼击车。","caption":""},{"image":"imgs/de/army/de_army_tankdestroyeriv_36.jpg","description":"1945年春天德国战场，德军（单位不明）一辆被击毁的（L/48）Ⅳ号坦克歼击车。","caption":""},{"image":"imgs/de/army/de_army_tankdestroyeriv_37.jpg","description":"在Dresden地区，德军（单位不明）一辆被击毁的（L/48）Ⅳ号坦克歼击车。注意该车车体上已涂上了防磁涂层，而车体侧面上的弹孔正是它被毁的原因。","caption":""}]}')}});